/* gcc check_cuda.c -o check_cuda -lcuda */
#include <stdio.h>
#include <cuda.h>
int main() {
  CUresult r = cuInit(0);
  if (r != CUDA_SUCCESS) {
    printf("cuInit failed %d\\n", r);
    return 2;
  }
  int driver_version = 0;
  cuDriverGetVersion(&driver_version);
  printf("driver %d\\n", driver_version);
  return 0;
}
